package com.primehr.rsp.selection.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.rsp.evaluation.domain.HrmpsbResolution;import jakarta.persistence.*;import org.hibernate.annotations.Nationalized;import java.math.BigDecimal;
@Entity @Table(name="rsp_selection_candidate_decision") public class SelectionCandidateDecision extends RspAuditedEntity{
 @Column(name="selection_case_id",nullable=false,length=36)private String selectionCaseId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Column(name="application_id",nullable=false,length=36)private String applicationId;@Column(name="applicant_id",nullable=false,length=36)private String applicantId;@Column(name="total_score",nullable=false,precision=12,scale=4)private BigDecimal totalScore;@Column(name="rank_number",nullable=false)private int rankNumber;@Column(name="tie_group",nullable=false)private int tieGroup;@Column(nullable=false)private boolean excluded;@Column(name="exclusion_reason",length=1000)private String exclusionReason;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private HrmpsbResolution.Recommendation recommendation;@Nationalized @Column(name="recommendation_reason",nullable=false,length=3000)private String recommendationReason;@Column(name="selected_case_key",length=36)private String selectedCaseKey;@Column(nullable=false)private boolean selected;
 protected SelectionCandidateDecision(){} public SelectionCandidateDecision(String agency,String selection,String candidate,String application,String applicant,BigDecimal score,int rank,int tie,boolean excluded,String exclusion,HrmpsbResolution.Recommendation recommendation,String recommendationReason){super(agency);selectionCaseId=requiredText(selection,"selectionCaseId");candidateId=requiredText(candidate,"candidateId");applicationId=requiredText(application,"applicationId");applicantId=requiredText(applicant,"applicantId");if(score==null||rank<1||tie<1)throw new IllegalArgumentException("Candidate evaluation values are invalid");totalScore=score;rankNumber=rank;tieGroup=tie;this.excluded=excluded;exclusionReason=optionalText(exclusion);this.recommendation=java.util.Objects.requireNonNull(recommendation);this.recommendationReason=requiredText(recommendationReason,"recommendationReason");}
 public void select(){if(excluded)throw new IllegalArgumentException("An excluded candidate cannot be selected");selected=true;selectedCaseKey=selectionCaseId;}public void clearSelection(){selected=false;selectedCaseKey=null;}
 public String getSelectionCaseId(){return selectionCaseId;}public String getCandidateId(){return candidateId;}public String getApplicationId(){return applicationId;}public String getApplicantId(){return applicantId;}public BigDecimal getTotalScore(){return totalScore;}public int getRankNumber(){return rankNumber;}public int getTieGroup(){return tieGroup;}public boolean isExcluded(){return excluded;}public String getExclusionReason(){return exclusionReason;}public HrmpsbResolution.Recommendation getRecommendation(){return recommendation;}public String getRecommendationReason(){return recommendationReason;}public boolean isSelected(){return selected;}
}
